import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { int x = Integer.parseInt(br.readLine().trim()); if (x <= 10) { out.println("YES"); } else { out.println("NO"); } } } out.flush(); out.close(); } }